export function PartyFilter(a="all"){return`\n        <div class="filter-container">\n            <label for="party-filter" class="filter-label">\n                <svg class="filter-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">\n                    <polygon points="22 3 2 3 10 12.46 10 19 14 21 14 12.46 22 3"></polygon>\n                </svg>\n                <span>Filter Party:</span>\n            </label>\n            <select id="party-filter" aria-label="Filter Prime Ministers by Political Party">\n                ${[{id:"all",label:"All Political Parties"},{id:"INC",label:"Indian National Congress (INC)"},{id:"BJP",label:"Bharatiya Janata Party (BJP)"},{id:"Janata Party",label:"Janata Party / Coalition"},{id:"Janata Dal",label:"Janata Dal / United Front"}].map(l=>`\n        <option value="${l.id}" ${a===l.id?"selected":""}>\n            ${l.label}\n        </option>\n    `).join("")}\n            </select>\n        </div>\n    `}